{
 "stablehlo_contract": [
  {
   "operation": "Program structure and types",
   "syntax": [
    {
     "id": "MOD.SYN.1",
     "rule": "program := `func.func @main(%arg: T, ...) -> T_out { op* ; return %v : T_out }`; each %name defined once"
    },
    {
     "id": "MOD.SYN.2",
     "rule": "op := `%r = \"stablehlo.NAME\"(operands) {attrs}? : (operand_types) -> result_type`"
    },
    {
     "id": "MOD.SYN.3",
     "rule": "int_list_attr := `array<i64: d0, d1, ...>`; int_attr := `N : i64`"
    }
   ],
   "type": [
    {
     "id": "MOD.TYP.1",
     "rule": "T := `tensor<d0 x ... x elem>`; scalar := `tensor<elem>`; elem ∈ {f32, i32, i64, i1}"
    }
   ],
   "semantics": [
    {
     "id": "MOD.SEM.1",
     "rule": "∀ op: no implicit broadcast; no implicit type promotion"
    }
   ]
  },
  {
   "operation": "stablehlo.pad",
   "syntax": [
    {
     "id": "PAD.SYN.1",
     "rule": "`%r = \"stablehlo.pad\"(%x, %pv) {edge_padding_low = array<i64: ...>, edge_padding_high = array<i64: ...>, interior_padding = array<i64: ...>} : (T_in, tensor<E>) -> T_out`"
    }
   ],
   "type": [
    {
     "id": "PAD.TYP.1",
     "rule": "type(padding_value) = tensor<element_type(operand)> = tensor<element_type(result)>"
    }
   ],
   "shape": [
    {
     "id": "PAD.SHP.1",
     "rule": "size(edge_padding_low) = size(edge_padding_high) = size(interior_padding) = rank(operand) ∧ 0 <= interior_padding"
    },
    {
     "id": "PAD.SHP.2",
     "rule": "shape(result) = edge_padding_low + shape(operand) + max(shape(operand) - 1, 0) * interior_padding + edge_padding_high"
    }
   ],
   "semantics": [
    {
     "id": "PAD.SEM.1",
     "rule": "result[low + j * (interior + 1)] = operand[j]; otherwise padding_value"
    }
   ]
  },
  {
   "operation": "stablehlo.constant",
   "syntax": [
    {
     "id": "CONST.SYN.1",
     "rule": "`%c = stablehlo.constant dense<v> : T` | `%c = \"stablehlo.constant\"() {value = dense<...> : T} : () -> T`"
    }
   ],
   "type": [
    {
     "id": "CONST.TYP.1",
     "rule": "type(value) = type(output); `dense<v> : T` is a splat of v over shape(T)"
    }
   ],
   "semantics": [
    {
     "id": "CONST.SEM.1",
     "rule": "f32(-inf) = `dense<0xFF800000>`; f32(+inf) = `dense<0x7F800000>`"
    }
   ]
  }
 ]
}

