Reply with the complete program in a single ```mlir code block.

```mlir
func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1e-12> : tensor<f32>  // epsilon to avoid div by zero
  // square each element: x^2
  %x_sq = stablehlo.multiply %x, %x : tensor<3x8xf32>
  // sum over last dimension (axis=1), result shape: tensor<3xf32>
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_sq = "stablehlo.reduce"(%x_sq, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>
  // sqrt of sum of squares
  %sqrt_sum = stablehlo.sqrt %sum_sq : tensor<3xf32>
  // add epsilon to avoid division by zero
  %denom = stablehlo.add %sqrt_sum, %c1 : tensor<3xf32>
  // broadcast denom from shape [3] to [3,8]
  %denom_bcast = stablehlo.broadcast_in_dim %denom
    {broadcast_dimensions = dense<array<i64: 0>> : tensor<1xi64>} : (tensor<3xf32>) -> tensor<3x8xf32>
  // divide x by denom_bcast elementwise
  %out = stablehlo.divide %x, %denom_bcast : tensor<3x8xf32>
  return %out : tensor<3x8xf32>
}
