  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<4x8xf32>

  // Compute sum_k exp(x[i,k]) by reducing over dimension 1
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce %exp_x, %init {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4xf32>

  // Broadcast sum_exp back to shape 4x8 for division
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp 
    {broadcast_dimensions = dense<0> : tensor<1xi64>} : tensor<4xf32> -> tensor<4x8xf32>

  // Divide exp(x) by sum_k exp(x[i,k]) to get softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_broadcast : tensor<4x8xf32>

  func.return %softmax : tensor<4x8xf32>
