    compare_type = #stablehlo<comparison_type TOTALORDER>
  } : (tensor<3x3xi32>, tensor<3x3xi32>) -> tensor<3x3xi1>

  // Create a constant tensor of zeros with the same shape and element type as input
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Broadcast zero to the shape of x
  %zero_tensor = stablehlo.broadcast_in_dim %zero
    : (tensor<f32>) -> tensor<3x3xf32> {broadcast_dimensions = []}

  // Select elements from x where mask is true, else zero
  %result = stablehlo.select %mask, %x, %zero_tensor : (tensor<3x3xi1>, tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xf32>

  func.return %result : tensor<3x3xf32>
