  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf for f32

  // Compute max over dim=1 for numerical stability: max_x[i] = max_j x[i,j]
  %max_x = "stablehlo.reduce"(%x, %c_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %m = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

