  %max_x_bcast = "stablehlo.broadcast_in_dim"(%max_x) {broadcast_dimensions = array<i64: 0} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Subtract max_x from x for numerical stability
  %x_stable = stablehlo.subtract %x, %max_x_bcast : tensor<7x8xf32>

