func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
  // Square each element: x^2
  %x_sq = stablehlo.multiply %x, %x : tensor<7x3xf32>

  // Create zero constant for reduction init
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>

  // Reduce sum over dimension 1 (columns) to get sum of squares per row
  %sum_sq = "stablehlo.reduce"(%x_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute sqrt of sum of squares (L2 norm per row)
  %l2_norm = stablehlo.sqrt %sum_sq : tensor<7xf32>

  // Broadcast l2_norm from shape [7] to [7x3] to match x shape
  %l2_norm_broadcast = "stablehlo.broadcast_in_dim"(%l2_norm) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x3xf32>

  // Divide each element by its row L2 norm
  %out = stablehlo.divide %x, %l2_norm_broadcast : tensor<7x3xf32>

  "stablehlo.return"(%out) : tensor<7x3xf32>
}
