func.func @main(%x: tensor<6xf32>) -> tensor<16xf32> {
  %c0 = stablehlo.constant 0.0 : f32
  %c0_6 = stablehlo.constant dense<0> : tensor<6xi64>
  %c0_16 = stablehlo.constant dense<0> : tensor<16xi64>
  %c1_6 = stablehlo.constant dense<1> : tensor<6xi64>
  %c3_6 = stablehlo.constant dense<3> : tensor<6xi64>
  %c2_6 = stablehlo.constant dense<2> : tensor<6xi64>

  // Pad %x to length 16 with zeros, inserting 2 zeros between elements.
  // We do this by padding each element with 2 zeros on the right, except the last element.
  // But pad op pads at the start and end, so we use a trick:
  // We create a tensor of shape [6,3] where each row is [x[i], 0, 0]
  // Then reshape to [18], then slice first 16 elements.

  // First, reshape x to [6,1]
  %x_reshaped = stablehlo.reshape %x : tensor<6xf32> to tensor<6x1xf32>

  // Create padding config: pad 0 on dim 0, pad 0 on dim 1 start, pad 2 on dim 1 end
  // But stablehlo.pad pads only at start and end of each dimension.
  // So pad with 0 at start and 2 at end on dim 1.
  %padding_low = stablehlo.constant dense<0, 0> : tensor<2xi64>
  %padding_high = stablehlo.constant dense<0, 2> : tensor<2xi64>

  %padded = stablehlo.pad %x_reshaped %c0 {
    padding_low = dense<0, 0> : tensor<2xi64>,
    padding_high = dense<0, 2> : tensor<2xi64>
  } : tensor<6x1xf32> to tensor<6x3xf32>

  // Now reshape to 18 elements
  %padded_reshaped = stablehlo.reshape %padded : tensor<6x3xf32> to tensor<18xf32>

  // Slice first 16 elements
  %start_indices = stablehlo.constant dense<0> : tensor<1xi64>
  %limit_indices = stablehlo.constant dense<16> : tensor<1xi64>
  %strides = stablehlo.constant dense<1> : tensor<1xi64>
  %out = stablehlo.slice %padded_reshaped [%start_indices] [%limit_indices] [%strides] : tensor<18xf32> to tensor<16xf32>

  func.return %out : tensor<16xf32>
}
