  // Compare idx_bcast == iota_bcast -> tensor<4x8xi1>
  %eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type S32>} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

