  %lt = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type S32>} : (tensor<4xi32>, tensor<i32>) -> tensor<4xi1>

