  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx from shape [5] to [5,8] with broadcast_dimensions=[0]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = dense<0> : tensor<i64>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast iota from shape [8] to [5,8] with broadcast_dimensions=[1]
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = dense<1> : tensor<i64>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_bcast == iota_bcast -> tensor<5x8xi1>
  %cmp = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Check idx in [0,7]: idx >= 0 and idx < 8
  %c0 = stablehlo.constant dense<0> : tensor<i32>
  %ge0 = "stablehlo.compare"(%idx, %c0) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>
  %lt8 = "stablehlo.compare"(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>

  // Logical AND of ge0 and lt8 to get valid mask per row
  // Since stablehlo does not have logical ops, use select: a AND b = select(a, b, false)
  %false = stablehlo.constant dense<false> : tensor<i1>
  %and_mask = "stablehlo.select"(%ge0, %lt8, %false) : (tensor<5xi1>, tensor<5xi1>, tensor<i1>) -> tensor<5xi1>

  // Broadcast and_mask from [5] to [5,8] with broadcast_dimensions=[0]
  %and_mask_bcast = "stablehlo.broadcast_in_dim"(%and_mask) {broadcast_dimensions = dense<0> : tensor<i64>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Final mask: cmp AND and_mask_bcast
  %final_mask = "stablehlo.select"(%and_mask_bcast, %cmp, %false) : (tensor<5x8xi1>, tensor<5x8xi1>, tensor<i1>) -> tensor<5x8xi1>

  // Select 1.0 where final_mask true else 0.0
  %out = "stablehlo.select"(%final_mask, %c1f, %c0f) : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  return %out : tensor<5x8xf32>
}
