  %init_sum = stablehlo.broadcast_in_dim %c_zero : tensor<f32> to tensor<4x1xf32> {broadcast_dimensions = [0, 1]}
  %sum_exp = stablehlo.reduce %exp, %init_sum {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x5xf32>, tensor<4x1xf32>) -> tensor<4x1xf32>

  // Broadcast sum_exp to shape 4x5 for division
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp : tensor<4x1xf32> to tensor<4x5xf32> {broadcast_dimensions = [0, 1]}

  // Divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<4x5xf32>

