func.func @main(%idx: tensor<5xi32>) -> tensor<5x8xf32> {
  // Create a tensor of shape [8] with values [0,1,2,3,4,5,6,7]
  %iota = stablehlo.iota {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast %idx to shape [5,8] to compare with %iota
  %idx_bcast = stablehlo.broadcast_in_dim %idx : tensor<5xi32> to tensor<5x8xi32> {broadcast_dimensions = dense<0> : tensor<1xi64>}
  %iota_bcast = stablehlo.broadcast_in_dim %iota : tensor<8xi32> to tensor<5x8xi32> {broadcast_dimensions = dense<1> : tensor<1xi64>}

  // Compare idx_bcast and iota_bcast for equality
  %cmp_eq = stablehlo.compare %idx_bcast, %iota_bcast 
    {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Create constant 1.0 and 0.0 tensors of shape [5x8]
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<5x8xf32> {broadcast_dimensions = dense<> : tensor<0xi64>}
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<5x8xf32> {broadcast_dimensions = dense<> : tensor<0xi64>}

  // Select 1.0 where equal, else 0.0
  %sel = stablehlo.select %cmp_eq, %one_bcast, %zero_bcast : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  // Now mask out rows where idx[n] is outside [0..7]
  // Create constants for bounds
  %zero_i32 = stablehlo.constant dense<0> : tensor<i32>
  %seven_i32 = stablehlo.constant dense<7> : tensor<i32>

  // Compare idx >= 0 and idx <= 7
  %ge_zero = stablehlo.compare %idx, %zero_i32 
    {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
  %le_seven = stablehlo.compare %idx, %seven_i32 
    {comparison_direction = #stablehlo<comparison_direction LE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>

  // Logical AND: ge_zero & le_seven
  %valid_idx = stablehlo.compare %ge_zero, %le_seven 
    {comparison_direction = #stablehlo<comparison_direction AND>, compare_type = #stablehlo<comparison_type NOTYPE>} : (tensor<5xi1>, tensor<5xi1>) -> tensor<5xi1>

  // Broadcast valid_idx to [5x8]
  %valid_idx_bcast = stablehlo.broadcast_in_dim %valid_idx : tensor<5xi1> to tensor<5x8xi1> {broadcast_dimensions = dense<0> : tensor<1xi64>}

  // Select final output: if valid_idx then sel else zero
  %final = stablehlo.select %valid_idx_bcast, %sel, %zero_bcast : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  return %final : tensor<5x8xf32>
}
