func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<4x8xf32>

  // Create zero constant for initial value of reduce (sum)
  %c0 = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %init = stablehlo.broadcast_in_dim %c0 {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<1xf32>
  // Actually, we need a scalar tensor for init, so just use %c0 directly.

  // Reduce sum over dimension 1 (the 8 dimension)
  %sum_exp = "stablehlo.reduce"(%exp_x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4xf32>

  // Broadcast sum_exp back to shape 4x8 for division
  %sum_exp_bcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = dense<0> : tensor<1xi64>} : (tensor<4xf32>) -> tensor<4x8xf32>

  // Divide exp_x by sum_exp_bcast to get softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_bcast : tensor<4x8xf32>

  return %softmax : tensor<4x8xf32>
}
