Reply with the complete program in a single ```mlir code block.

```mlir
func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1e-12> : tensor<f32>  // small epsilon to avoid div by zero
  %c2 = stablehlo.constant dense<1> : tensor<f32>

  // square each element: x^2
  %x_sq = stablehlo.multiply %x, %x : tensor<7x3xf32>

  // sum over last dimension (axis=1), keep shape [7]
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_sq = "stablehlo.reduce"(%x_sq, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7xf32>

  // add epsilon for numerical stability
  %sum_sq_eps = stablehlo.add %sum_sq, %c1 : tensor<7xf32>

  // sqrt of sum of squares
  %norm = stablehlo.sqrt %sum_sq_eps : tensor<7xf32>

  // broadcast norm to shape [7x3]
  %norm_bcast = "stablehlo.broadcast_in_dim"(%norm) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x3xf32>

  // divide x by norm
  %out = stablehlo.divide %x, %norm_bcast : tensor<7x3xf32>

  return %out : tensor<7x3xf32>
}
