  // Create a constant zero tensor of shape [3] to pad between elements
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_pad = stablehlo.constant dense<0.0> : tensor<3xf32>

  // Reshape input to [8,1] to prepare for padding
  %x_reshaped = stablehlo.reshape %x : tensor<8xf32> to tensor<8x1xf32>

  // Pad each element with two zeros to the right, resulting in shape [8,3]
