  %pad = stablehlo.pad %x_reshaped low=0 high=2 padding_value=%c0 : tensor<8x1xf32> to tensor<8x3xf32>

  // Reshape to [24] (8*3)
  %flat = stablehlo.reshape %pad : tensor<8x3xf32> to tensor<24xf32>

  // Slice to get first 22 elements
  %start = stablehlo.constant dense<0> : tensor<i64>
  %limit = stablehlo.constant dense<22> : tensor<i64>
  %stride = stablehlo.constant dense<1> : tensor<i64>
  %out = stablehlo.slice %flat {start_indices = [0], limit_indices = [22], strides = [1]} : tensor<24xf32> to tensor<22xf32>

  func.return %out : tensor<22xf32>
