func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
  %cst_0 = stablehlo.constant 0.0 : f32
  %cst_1 = stablehlo.constant 1e-6 : f32

  // Square each element: x^2
  %squared = stablehlo.multiply %x, %x : tensor<3x8xf32>

  // Reduce sum over axis 1 (columns) to get sum of squares per row: shape tensor<3xf32>
  %sum_squares = stablehlo.reduce %squared, %cst_0 {
    dimensions = [1]
  } : tensor<3x8xf32>, tensor<f32> -> tensor<3xf32>

  // Add epsilon for numerical stability: sum_squares + 1e-6
  %sum_squares_eps = stablehlo.add %sum_squares, %cst_1 : tensor<3xf32>

  // Compute sqrt of sum_squares_eps: shape tensor<3xf32>
  %l2_norm = stablehlo.sqrt %sum_squares_eps : tensor<3xf32>

  // Broadcast l2_norm to shape tensor<3x8xf32> for division
  %l2_norm_broadcast = stablehlo.broadcast_in_dim %l2_norm 
    : tensor<3xf32> to tensor<3x8xf32> 
    broadcast_dimensions = [0]

  // Divide each element by the row L2 norm
  %out = stablehlo.divide %x, %l2_norm_broadcast : tensor<3x8xf32>

  stablehlo.return %out : tensor<3x8xf32>
}
